use super::kernels::*;

fn close(got: &[f64], want: &[f64], tol: f64, what: &str) {
    assert_eq!(got.len(), want.len(), "{what}: length {got:?} vs {want:?}");
    let scale = 1.0 + want.iter().fold(0.0f64, |m, v| m.max(v.abs()));
    for (i, (g, w)) in got.iter().zip(want).enumerate() {
        assert!(
            (g - w).abs() <= tol * scale,
            "{what}[{i}]: got {g:e}, want {w:e}\n got  {got:?}\n want {want:?}"
        );
    }
}

/// Every wanted root has a distinct computed root within `tol` (order ignored).
fn same_roots(got: &[(f64, f64)], want: &[(f64, f64)], tol: f64, what: &str) {
    assert_eq!(got.len(), want.len(), "{what}: {got:?} vs {want:?}");
    let mut used = vec![false; got.len()];
    for w in want {
        let (best, d) = got
            .iter()
            .enumerate()
            .filter(|(i, _)| !used[*i])
            .map(|(i, g)| (i, (g.0 - w.0).hypot(g.1 - w.1)))
            .fold(
                (usize::MAX, f64::INFINITY),
                |a, b| if b.1 < a.1 { b } else { a },
            );
        let scale = 1.0 + w.0.hypot(w.1);
        assert!(
            d <= tol * scale,
            "{what}: no match for {w:?} (nearest off by {d:e}) in {got:?}"
        );
        used[best] = true;
    }
}

// ------------------------------------------------------------------ NumPy parity

#[test]
fn polyval_matches_numpy() {
    let got: Vec<f64> = PV_X.iter().map(|&x| polyval(&PV_P, x)).collect();
    close(&got, &PV_Y, 1e-14, "polyval");
    assert_eq!(polyval(&[], 3.0), 0.0);
    assert_eq!(polyval(&[4.0], 3.0), 4.0);
}

#[test]
fn add_sub_mul_match_numpy() {
    close(&polyadd(&A, &B), &ADD_AB, 1e-15, "polyadd");
    close(&polysub(&A, &B), &SUB_AB, 1e-15, "polysub");
    close(&polysub(&B, &A), &SUB_BA, 1e-15, "polysub reversed");
    close(
        &polyadd(&[1.0, 2.0], &[-1.0, 3.0]),
        &ADD_CANCEL,
        0.0,
        "polyadd keeps leading zero",
    );
    close(&polymul(&A, &B), &MUL_AB, 1e-14, "polymul");
}

#[test]
fn polydiv_matches_numpy() {
    let (q, r) = polydiv(&A, &B);
    close(&q, &DIV_AB_Q, 1e-14, "quotient");
    close(&r, &DIV_AB_R, 1e-14, "remainder");
    let (q, r) = polydiv(&U, &V);
    close(&q, &DIV_UV_Q, 1e-14, "quotient 2");
    close(&r, &DIV_UV_R, 1e-14, "remainder 2");
    let (q, r) = polydiv(&[1.0, -3.0, 2.0], &[1.0, -1.0]);
    close(&q, &DIV_EXACT_Q, 1e-15, "exact quotient");
    close(&r, &DIV_EXACT_R, 1e-15, "exact remainder");
    let (q, r) = polydiv(&[3.0, 1.0], &[1.0, 0.0, 0.0]);
    close(&q, &DIV_SMALL_Q, 0.0, "deg(u) < deg(v) quotient");
    close(&r, &DIV_SMALL_R, 0.0, "deg(u) < deg(v) remainder");
}

#[test]
fn polyder_and_polyint_match_numpy() {
    close(&polyder(&A, 1), &DER1, 1e-15, "polyder");
    close(&polyder(&A, 2), &DER2, 1e-15, "polyder m=2");
    assert!(polyder(&A, 4).is_empty() && DER4.is_empty());
    assert_eq!(polyder(&A, 0), A);
    close(&polyint(&A, 1, &[]), &INT1, 1e-15, "polyint");
    close(&polyint(&A, 2, &[1.0, 2.0]), &INT2K, 1e-15, "polyint m=2 k");
    close(
        &polyint(&A, 3, &[4.0]),
        &INT3K1,
        1e-15,
        "polyint broadcast k",
    );
    assert_eq!(polyint(&A, 0, &[]), A);
}

#[test]
fn polyfit_matches_numpy() {
    let fits: [(usize, &[f64]); 5] = [
        (1, &FIT_D1),
        (2, &FIT_D2),
        (3, &FIT_D3),
        (5, &FIT_D5),
        (8, &FIT_D8),
    ];
    for (d, want) in fits {
        let got = polyfit(&FIT_X, &FIT_Y, d);
        // Compare in the scaled sense: coefficient c_j multiplies x^(d-j) with x in [0, 2].
        for (j, (g, w)) in got.iter().zip(want).enumerate() {
            let tol = 1e-8 * (1.0 + w.abs());
            assert!(
                (g - w).abs() < tol,
                "deg {d} coef {j}: got {g:e}, want {w:e}"
            );
        }
    }
}

#[test]
fn polyfit_handles_badly_scaled_abscissae() {
    let got = polyfit(&FIT2_X, &FIT2_Y, 2);
    // The fitted curve (not the raw coefficients, which cancel heavily) must agree with NumPy's.
    for &x in &FIT2_X {
        let g = polyval(&got, x);
        let w = polyval(&FIT2_D2, x);
        assert!((g - w).abs() < 1e-9, "x={x}: {g} vs {w}");
    }
}

#[test]
fn roots_match_numpy_as_sets() {
    for (i, (p, want)) in ROOT_CASES.iter().enumerate() {
        let got = roots(p);
        // Wilkinson-10 is ill-conditioned: NumPy itself is only good to ~1e-6.
        let tol = if i == 8 { 1e-5 } else { 1e-8 };
        same_roots(&got, want, tol, &format!("case {i} {p:?}"));
    }
}

#[test]
fn roots_order_matches_numpy_on_simple_cases() {
    // (x-1)(x-2)(x-3) -> [3, 2, 1] exactly like np.roots.
    let r = roots(&[1.0, -6.0, 11.0, -6.0]);
    close(
        &r.iter().map(|c| c.0).collect::<Vec<_>>(),
        &[3.0, 2.0, 1.0],
        1e-12,
        "re",
    );
    assert!(r.iter().all(|c| c.1 == 0.0));
    // Trailing zero roots are appended last.
    let r = roots(&[0.0, 0.0, 1.0, -3.0, 2.0, 0.0, 0.0]);
    assert_eq!(r.len(), 4);
    assert!((r[0].0 - 2.0).abs() < 1e-12 && (r[1].0 - 1.0).abs() < 1e-12);
    assert_eq!((r[2], r[3]), ((0.0, 0.0), (0.0, 0.0)));
    // Conjugate pairs: positive imaginary part first.
    let r = roots(&[1.0, 0.0, 1.0]);
    assert!(r[0].1 > 0.0 && r[1].1 < 0.0 && (r[0].1 + r[1].1).abs() < 1e-15);
    // Every fixture case (incl. random and badly scaled ones) comes out in NumPy's order.
    for (i, (p, want)) in ROOT_CASES.iter().enumerate() {
        let got = roots(p);
        assert_eq!(got.len(), want.len(), "case {i}");
        for (k, (g, w)) in got.iter().zip(want.iter()).enumerate() {
            let tol = if i == 8 { 1e-5 } else { 1e-7 };
            assert!(
                (g.0 - w.0).hypot(g.1 - w.1) < tol * (1.0 + w.0.hypot(w.1)),
                "case {i} root {k}: got {g:?}, NumPy {w:?}"
            );
        }
    }
}

#[test]
fn degenerate_root_inputs() {
    assert!(roots(&[]).is_empty());
    assert!(roots(&[5.0]).is_empty());
    assert!(roots(&[0.0, 0.0]).is_empty());
    assert_eq!(roots(&[2.0, -4.0]), vec![(2.0, 0.0)]);
    assert_eq!(roots(&[1.0, 0.0, 0.0]), vec![(0.0, 0.0), (0.0, 0.0)]);
}

